#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Google Map Tiles API (satélite 2D) para el editor de predios (#26).
# Objetivo: costo cero. La clave queda restringida y con tope diario de
# pedidos por debajo del cupo gratis (100.000 por mes), así nunca factura.
# Correr desde la raíz del repo: bash scripts/configurar-google-map-tiles.sh
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE=".env.local"
TOTAL_STAGES=9
TOPE_DIARIO=3000 # 3.000 × 31 días = 93.000 < 100.000 gratis por mes

banner "Google Map Tiles API · editor de predios (costo cero)"

stage "Proyecto de Google Cloud"
say "Vamos a usar un proyecto solo para los mapas de El Club."
open_url "https://console.cloud.google.com/projectcreate"
step "Creá un proyecto nuevo (por ejemplo «el-club-mapas») o elegí uno existente."
step "Arriba a la izquierda, dejalo seleccionado como proyecto activo."
ask GCP_PROYECTO "ID del proyecto (no secreto, solo para los links que siguen):"

stage "Cuenta de facturación"
say "Google pide una cuenta de facturación con tarjeta aunque no se pase del cupo gratis."
note "En las etapas 5 y 6 ponemos el tope diario y una alerta, para que nunca cobre."
open_url "https://console.cloud.google.com/billing/linkedaccount?project=${GCP_PROYECTO}"
step "Vinculá una cuenta de facturación al proyecto (creala si no tenés)."
step "Si te ofrece una prueba gratuita o un upgrade, no hace falta aceptar nada más."
pause "Enter cuando el proyecto tenga facturación vinculada"

stage "Habilitar la Map Tiles API"
open_url "https://console.cloud.google.com/apis/library/tile.googleapis.com?project=${GCP_PROYECTO}"
step "Tocá «Habilitar» (Enable) en Map Tiles API."
warn "No habilites la Maps JavaScript API ni otras: no las usamos."
pause "Enter cuando diga que la API está habilitada"

stage "Crear y restringir la clave"
open_url "https://console.cloud.google.com/apis/credentials?project=${GCP_PROYECTO}"
step "«Crear credenciales» → «Clave de API»."
step "Abrí la clave, ponele de nombre «el-club-map-tiles»."
step "Restricciones de aplicación → «Sitios web (referentes HTTP)». Agregá:"
note "    http://localhost:3000/*"
note "    https://<dominio de la app en producción>/*"
note "    https://*.vercel.app/*   (previews; si preferís, solo el del proyecto)"
step "Restricciones de API → «Restringir clave» → marcá solo «Map Tiles API»."
step "Guardá y copiá la clave."
ask_secret NEXT_PUBLIC_GOOGLE_MAPS_API_KEY "Pegá la clave (no se muestra):"
write_env NEXT_PUBLIC_GOOGLE_MAPS_API_KEY "$NEXT_PUBLIC_GOOGLE_MAPS_API_KEY"

stage "Tope diario de pedidos (lo que garantiza costo cero)"
say "Con un tope de ${TOPE_DIARIO} pedidos por día nunca se llega a los 100.000 gratis del mes."
say "Pasado el tope, Google rechaza los pedidos en vez de cobrarlos."
open_url "https://console.cloud.google.com/apis/api/tile.googleapis.com/quotas?project=${GCP_PROYECTO}"
step "En la lista de cuotas, buscá las que digan «per day» (por día)."
step "En cada una: los tres puntos o el lápiz → «Editar cuota» → ${TOPE_DIARIO} → Enviar."
note "Si alguna fila es «per minute», dejala como está."
note "Si no aparece ninguna «per day», avisame y lo vemos antes de usar la clave."
confirm "¿Quedó el tope diario en ${TOPE_DIARIO}?" || warn "Sin tope diario no hay garantía de costo cero: no subas la clave a Vercel hasta ponerlo."

stage "Alerta de presupuesto (aviso, no frena)"
open_url "https://console.cloud.google.com/billing/budgets"
step "«Crear presupuesto» → alcance: el proyecto ${GCP_PROYECTO}."
step "Monto: US\$1. Alertas al 50 % y 100 %, por mail a vos."
note "El presupuesto solo avisa; lo que frena de verdad es el tope de la etapa 5."
pause "Enter cuando el presupuesto esté creado"

stage "Términos de la Map Tiles API"
say "Falta confirmar que se puede usar un visor que no es de Google (MapLibre) mostrando su atribución."
open_url "https://developers.google.com/maps/documentation/tile/policies"
step "Leé la sección de atribución: logo de Google y el texto de copyright visibles, sin taparlos."
if confirm "¿Los términos permiten usar MapLibre mostrando la atribución de Google?"; then
  say "Perfecto: anotalo en #26."
else
  SKIPPED+=("Aclarar en #26 los términos de la Map Tiles API para MapLibre")
  warn "Anotá en #26 qué encontraste; mientras tanto el mock sigue con Esri."
fi

stage "Clave en Vercel"
open_url "https://vercel.com/dashboard"
step "Proyecto de El Club → Settings → Environment Variables → Add."
step "Nombre: NEXT_PUBLIC_GOOGLE_MAPS_API_KEY · Valor: la misma clave."
step "Entornos: Production, Preview y Development."
step "Hacé un redeploy para que la tome (las NEXT_PUBLIC_ se leen al compilar)."
pause "Enter cuando esté guardada en Vercel"

stage "Prueba"
say "Pido una sesión de tiles satelitales como lo hace el editor, desde localhost."
if command -v curl >/dev/null 2>&1; then
  RESPUESTA=$(curl -s -X POST \
    "https://tile.googleapis.com/v1/createSession?key=${NEXT_PUBLIC_GOOGLE_MAPS_API_KEY}" \
    -H "Content-Type: application/json" -H "Referer: http://localhost:3000/" \
    -d '{"mapType":"satellite","language":"es-AR","region":"AR"}' || true)
  if printf '%s' "$RESPUESTA" | grep -q '"session"'; then
    printf '  %s✓ La clave funciona: Google devolvió una sesión satelital.%s\n' "$GREEN" "$RESET"
  else
    warn "Google no devolvió una sesión. Respuesta:"
    note "$RESPUESTA"
    SKIPPED+=("Revisar la clave: createSession falló (ver respuesta arriba)")
  fi
else
  SKIPPED+=("Probar la clave: npm run dev y abrir http://localhost:3000/mocks/predio?variant=B")
fi
say "Para verlo: npm run dev y abrí http://localhost:3000/mocks/predio?variant=B → «Editar predio»."
pause "Enter para terminar"

finish
